<template>
  <div class="v3-workout-result v3-screen" :data-rpe-state="rpe===null?'unreported':'reported'">
    <sf-page-layout title="Workout Data" :glass="false" @back="$emit('action','back')">
      <section class="workout-result-summary">
        <div class="workout-result-summary__heading"><span class="workout-result-summary__check"><sf-icon name="check" :size="19"/></span><div><h1>Workout complete</h1></div></div>
        <div class="workout-result-metrics"><div v-for="metric in metrics" :key="metric.label"><span>{{ metric.label }}</span><strong>{{ metric.value }}<small v-if="metric.unit">{{ metric.unit }}</small></strong></div></div>
      </section>
      <sf-segmented-control v-model="panel" :items="panels" label="Workout result sections" @change="$emit('panel-change',$event)"/>
      <section v-if="panel==='overview'" id="result-overview" role="tabpanel" aria-label="Overview" class="workout-result-overview">
        <sf-card v-if="rpe===null" class="workout-rpe-entry">
          <div class="workout-result-label"><sf-icon name="heart-pulse" :size="18"/><span>Your effort</span></div><h2>How did that feel?</h2><p>Rate your effort to complete your workout log.</p><sf-button @click="openRpe">Report RPE</sf-button>
        </sf-card>
        <template v-else>
          <div class="workout-rpe-saved"><div><span>Effort recorded</span><strong>RPE {{ rpe }} <small>/ 10 · {{ effortLabel(rpe) }}</small></strong></div><button type="button" @click="openRpe" aria-label="Edit RPE">Edit</button></div>
          <sf-insight-card v-if="hasInsight||loading" class="result-insight" :rpe="rpe" :saved="hasInsight&&!loading" :body="body" :busy="loading" :state="loading?'insight-loading':'saved-insight'" @ask="$emit('action','coach-workout')"/>
          <sf-card v-else class="workout-insight-entry">
            <div class="workout-result-label"><img :src="orb" width="28" height="28" alt=""/><span>AI Coach Insight</span><sf-badge>Premium</sf-badge></div><h2>Understand your effort.</h2><p>Get a personal analysis of your workout and how it felt.</p><sf-button @click="$emit('action','generate-insight')">Get workout analysis</sf-button>
          </sf-card>
        </template>
        <button type="button" class="workout-result-details-link" @click="showDetails">View detailed workout data <sf-icon name="arrow" :size="16"/></button>
      </section>
      <section v-else id="result-data" role="tabpanel" aria-label="Detailed data" class="workout-result-data">
        <sf-card class="workout-heart-rate"><div class="workout-heart-rate__heading"><h2><sf-icon name="heart-pulse" :size="18"/>Heart rate</h2><div><span>Avg <strong>99</strong></span><span>Max <strong>125</strong></span><small>BPM</small></div></div>
          <svg viewBox="0 0 300 122" role="img" aria-label="Heart rate throughout the workout, average 99 and maximum 125 beats per minute"><defs><linearGradient id="result-heart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ff5d63" stop-opacity=".18"/><stop offset="1" stop-color="#ff5d63" stop-opacity="0"/></linearGradient></defs><path d="M0 26H300M0 62H300M0 98H300" stroke="currentColor" opacity=".1" stroke-dasharray="3 4"/><path d="M0 100L8 103 16 99 24 104 32 95 40 98 47 63 55 88 63 76 70 82 78 59 86 73 94 66 102 70 110 60 118 69 126 48 134 72 142 58 150 73 158 56 166 70 174 49 182 67 190 62 198 39 206 65 214 52 222 69 230 41 238 61 246 35 254 54 262 42 270 58 278 35 286 49 294 39 300 45V122H0Z" fill="url(#result-heart-fill)"/><path d="M0 100L8 103 16 99 24 104 32 95 40 98 47 63 55 88 63 76 70 82 78 59 86 73 94 66 102 70 110 60 118 69 126 48 134 72 142 58 150 73 158 56 166 70 174 49 182 67 190 62 198 39 206 65 214 52 222 69 230 41 238 61 246 35 254 54 262 42 270 58 278 35 286 49 294 39 300 45" fill="none" stroke="#fb4e55" stroke-width="1.5"/></svg><div class="workout-chart-axis"><span>0:00</span><span>20:00</span><span>40:23</span></div>
        </sf-card>
        <sf-card title="Heart rate zones" class="workout-heart-zones"><div v-for="zone in zones" :key="zone.label"><span>{{ zone.label }}</span><i><b :style="{width:zone.value+'%',background:zone.color}"/></i><strong>{{ zone.value }}%</strong></div></sf-card>
        <sf-card title="Session details" class="workout-session-details"><div><span>Duration</span><strong>40:23</strong></div><div><span>Calories</span><strong>876.1 kcal</strong></div><div><span>Distance</span><strong>8.6 mi</strong></div><div><span>Steps</span><strong>9,999</strong></div></sf-card>
      </section>
    </sf-page-layout>
    <sf-sheet v-model="rpeOpen" title="How hard was your workout?" contained :resizable="false">
      <div class="workout-rpe-picker"><p>Choose your perceived effort.</p><div class="workout-rpe-picker__value"><strong>{{ selection===null?'—':selection }}</strong><span>{{ selection===null?'Select a rating':effortLabel(selection) }}</span></div><div class="workout-rpe-options" role="radiogroup" aria-label="Perceived effort from 1 to 10"><button v-for="n in 10" :key="n" type="button" role="radio" :aria-checked="selection===n?'true':'false'" :aria-label="'RPE '+n+' · '+effortLabel(n)" :tabindex="selection===n||selection===null&&n===1?0:-1" @click="selection=n" @keydown="navigateRpe($event,n)">{{ n }}</button></div><div class="workout-rpe-scale"><span>Very easy</span><span>Maximum effort</span></div></div>
      <template #footer><sf-button :disabled="selection===null" @click="submitRpe">Save RPE</sf-button></template>
    </sf-sheet>
  </div>
</template>
<script>
import {SfPageLayout,SfCard,SfButton,SfIcon,SfSheet,SfSegmentedControl,SfBadge,SfInsightCard} from '@/design-system'
const efforts=['Very easy','Easy','Light','Moderate','Somewhat hard','Hard','Very hard','Very hard','Extremely hard','Maximum effort']
export default {
  components:{SfPageLayout,SfCard,SfButton,SfIcon,SfSheet,SfSegmentedControl,SfBadge,SfInsightCard},
  props:{rpe:{type:Number,default:null},hasInsight:Boolean,loading:Boolean,body:String,reviewPanel:String},
  data(){return {panel:this.reviewPanel==='details'?'details':'overview',rpeOpen:false,selection:null,panels:[{value:'overview',label:'Overview',panelId:'result-overview'},{value:'details',label:'Detailed data',panelId:'result-data'}],metrics:[{label:'Time',value:'40:23'},{label:'Calories',value:'876.1',unit:'kcal'},{label:'Distance',value:'8.6',unit:'mi'},{label:'Avg heart rate',value:'99',unit:'BPM'}],zones:[{label:'Zone 1',value:10,color:'#bce7a1'},{label:'Zone 2',value:20,color:'#7bbd56'},{label:'Zone 3',value:46,color:'#ffc941'},{label:'Zone 4',value:24,color:'#f85d62'}]}},
  computed:{orb(){return process.env.BASE_URL+'assets/figma/restored/orbs/insight.png'}},
  watch:{reviewPanel(value){this.panel=value==='details'?'details':'overview'}},
  methods:{effortLabel(n){return efforts[n-1]},openRpe(){this.selection=this.rpe;this.rpeOpen=true},submitRpe(){if(this.selection===null)return;this.$emit('submit-rpe',this.selection);this.rpeOpen=false},showDetails(){this.panel='details';this.$emit('panel-change','details')},navigateRpe(event,n){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();this.selection=event.key==='Home'?1:event.key==='End'?10:Math.min(10,Math.max(1,n+(event.key==='ArrowRight'?1:-1)));this.$nextTick(()=>this.$el.querySelectorAll('.workout-rpe-options button')[this.selection-1].focus())}}
}
</script>
